syntax:
ios_base& boolalpha(ios_base& str); //Example manipulator

//Implementation (simplified):
ios_base& boolalpha(ios_base& str) {
  str.setf(std::ios_base::boolalpha);
  return str;
}

code_example:
#include <iostream>
#include <iomanip>
int main() {
  bool value = true;
  std::cout << value << std::endl; //Default output
  std::cout << std::boolalpha << value << std::endl; // Output as "true"
  std::cout << std::noboolalpha << value << std::endl; //Back to default
  return 0;
}
